 "content": "from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r,c) in seen:
                continue
            q = [(r,c)]; seen.add((r,c)); cells=[]
            while q:
                y,x=q.pop(); cells.append((y,x))
                for dy in (-1,0,1):
                    for dx in (-1,0,1):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<h and 0<=nx<w and grid[ny][nx]!=0 and (ny,nx) not in seen:
                            seen.add((ny,nx)); q.append((ny,nx))
            if len(cells)>=4:
                comps.append(cells)
    comps.sort(key=len, reverse=True)
    if len(comps)<2:
        return []
    def crop(cells):
        r0=min(r for r,c in cells); r1=max(r for r,c in cells)
        c0=min(c for r,c in cells); c1=max(c for r,c in cells)
        a=[[grid[r][c] for c in range(c0,c1+1)] for r in range(r0,r1+1)]
        return a
    a,b=map(crop,comps[:2])
    ha,wa=len(a),len(a[0]); hb,wb=len(b),len(b[0])
    # Align corresponding figures by minimizing cell disagreements over translations.
    best=None
    for oy in range(-hb,ha+1):
        for ox in range(-wb,wa+1):
            y0=min(0,oy); x0=min(0,ox); y1=max(ha,oy+hb); x1=max(wa,ox+wb)
            mismatch=0
            for y in range(y0,y1):
                for x in range(x0,x1):
                    va=a[y][x] if 0<=y<ha and 0<=x<wa else 0
                    yy,xx=y-oy,x-ox
                    vb=b[yy][xx] if 0<=yy<hb and 0<=xx<wb else 0
                    mismatch += va != vb
            score=(mismatch, abs(oy), abs(ox))
            if best is None or score<best[0]: best=(score,oy,ox)
    _,oy,ox=best
    y0=min(0,oy); x0=min(0,ox); y1=max(ha,oy+hb); x1=max(wa,ox+wb)
    out=[]
    for y in range(y0,y1):
        out.append([8 if (a[y][x] if 0<=y<ha and 0<=x<wa else 0) != (b[y-oy][x-ox] if 0<=y-oy<hb and 0<=x-ox<wb else 0) else 0 for x in range(x0,x1)])
    coords=[(r,c) for r,row in enumerate(out) for c,v in enumerate(row) if v]
    if not coords: return [[0]]
    r0=min(r for r,c in coords); r1=max(r for r,c in coords)
    c0=min(c for r,c in coords); c1=max(c for r,c in coords)
    return [row[c0:c1+1] for row in out[r0:r1+1]]
